#!/usr/bin/env python3
import json
from pathlib import Path
proof=Path(__file__).resolve().parents[2]/'docs/proof/runtime-observation/milestone-2'
data=json.loads((proof/'delivery.json').read_text())
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Milestone 2 · One delivery at a time</title><style>body{font:16px/1.6 system-ui;max-width:900px;margin:3rem auto;padding:0 1rem;background:#f5f3ee;color:#243431}h1{font-size:2.5rem;line-height:1.1}.card{background:white;border:1px solid #b4c4ba;padding:1rem;margin:1rem 0}pre{white-space:pre-wrap;max-height:420px;overflow:auto}input{width:100%}b{font-size:1.5rem}li{padding:.4rem}small{color:#52645e}</style><small>BEAM LISP / MILESTONE 2</small><h1>One delivery. No backlog.</h1><p>Recorded against the compiled BL namespace. The first consumer holds its delivery while resource data changes; the next delivery resynchronizes, then both owners are disposed.</p><ol id="events"></ol><label for="delivery">Inspect a delivery</label><input id="delivery" type="range" min="0" max="1" value="0" step="1"><div class="card"><b id="title"></b><p id="state"></p><pre id="changes"></pre></div><details><summary>Raw evidence</summary><pre id="raw"></pre></details><p>Sequence gaps mean unseen samples, not proven packet loss. Coalesced ticks count this subscriber's actual skipped deliveries. No physical audio/video measurement is made.</p><script type="application/json" id="data">DATA</script><script>const d=JSON.parse(document.getElementById('data').textContent),el=id=>document.getElementById(id);for(const e of d.events){const li=document.createElement('li');li.textContent=`${e.atMs.toFixed(1)} ms · ${e.name}`;el('events').append(li);}function show(){const i=Number(el('delivery').value),v=d.deliveries[i];el('title').textContent=`Delivery ${i+1} · ${v.atMs.toFixed(1)} ms`;el('state').textContent=`${v.metadata.coalesced} coalesced ticks · resource value ${v.rows[0].resources[0].data.value}`;el('changes').textContent=JSON.stringify(v.metadata,null,2);}el('delivery').oninput=show;show();el('raw').textContent=JSON.stringify(d,null,2);</script></html>'''
(proof/'report.html').write_text(page.replace('DATA',json.dumps(data).replace('</','<\\/')))
